		{"helm ordinary", helmArgs(scope, "charts/app", binary, "template"), []string{"template", "charts/app"}},
		{"kustomize ordinary", kustomizeArgs(scope, "kustomizations/dev", binary), []string{"build", "kustomizations/dev"}},
