			t.Errorf("%s: args = %q, want %q", tt.name, tt.got.Args, tt.want)
		}
		if tt.got.Dir != "/repo" {
			t.Errorf("%s: dir = %q", tt.name, tt.got.Dir)
		}
	}
}

